struct ManualPage { let id: Int; let title: String }
func pageTitle(_ values: [ManualPage], index: Int) -> String {
    guard values.indices.contains(index) else { return "Нет страницы" }
    return values[index].title
}
let values = [ManualPage(id: 5, title: "Введение")]
assert(pageTitle(values, index: 1) == "Нет страницы")
assert(pageTitle(values, index: -1) == "Нет страницы")
assert(pageTitle(values, index: 0) == "Введение")

Стек указывает вызов, locals дают конкретный вход. indices.contains проверяет нижнюю и верхнюю границы; exception breakpoint не является универсальной ловушкой Swift trap.

