import UIKit
final class ToastOverlay: UIView {}
let root = UIView(frame: CGRect(x: 0, y: 0, width: 200, height: 100))
let button = UIButton(frame: CGRect(x: 20, y: 20, width: 60, height: 30))
let overlay = ToastOverlay(frame: root.bounds)
root.addSubview(button)
root.addSubview(overlay)
// View Hierarchy: overlay выше button, оба видимы.
// overlay прозрачен, но hitTest выбирает его.
overlay.isUserInteractionEnabled = false
assert(root.hitTest(CGPoint(x: 40, y: 30), with: nil) === button)

Полностью декоративный overlay не участвует в hit-testing. Прозрачный фон сам по себе не отключает взаимодействие; исправление проверяется идентичностью найденной кнопки.
